#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const int MOD1=998244353, MOD2=1e9+7, BASE=1e6;
vector<int> sequence[7];
int prefixSum[7];
long long totalCount, currentOrder, totalAnswer;

void generateSequences(int start, int level) {
    ++currentOrder;
    sequence[level].push_back((currentOrder - start + MOD1) % MOD1);
    (prefixSum[level] += sequence[level].back()) %= MOD2;
    if (level == 6) return;
    for (int digit=0; digit<=9; ++digit) {
        generateSequences(start*10 + digit, level+1);
    }
}

void traverseNumbers(long long x) {
    if (x > totalCount) return;
    if (x*BASE + BASE - 1 <= totalCount && x*BASE*10 > totalCount) {
        long long savedOrder = currentOrder;
        for (int i=0, factor=1; i<=6; ++i, factor*=10) {
            int size=sequence[i].size();
            int delta=((savedOrder - x*factor) % MOD1 + MOD1) % MOD1;
            int pos=lower_bound(sequence[i].begin(), sequence[i].end(), MOD1 - delta) - sequence[i].begin();
            totalAnswer = (totalAnswer + 1LL*delta*size + prefixSum[i]) % MOD2;
            totalAnswer = (totalAnswer - 1LL*(size - pos)*MOD1 + MOD2) % MOD2;
            currentOrder += size;
        }
        return;
    }
    ++currentOrder;
    totalAnswer = (totalAnswer + ((currentOrder - x) % MOD1 + MOD1) % MOD1) % MOD2;
    for (int digit=0; digit<=9; ++digit) {
        traverseNumbers(x*10 + digit);
    }
}

int main() {
    long long n_input;
    cin >> n_input;
    totalCount = n_input;
    generateSequences(0,0);
    currentOrder=0;
    for (int i=0; i<=6; ++i) sort(sequence[i].begin(), sequence[i].end());
    for (int i=1; i<=9; ++i) traverseNumbers(i);
    cout << totalAnswer;
    return 0;
}
